BEGIN TRANSACTION;
ALTER TABLE [dbo].[Stock] DROP CONSTRAINT [CK_Changed];
ALTER TABLE [dbo].[Stock] WITH CHECK ADD CONSTRAINT [CK_Changed] CHECK ([Price]>=(0));
COMMIT TRANSACTION;
GO
